    public void testIntegrate_StepRejection_And_Recovery() {
        // Arrange
        double targetTime = 0.1;
        when(mockEquations.getCompleteState()).thenReturn(new double[]{1.0});
        when(mockEquations.getTime()).thenReturn(0.0);

        // First call to estimateError returns > 1.0 (rejection), second returns < 1.0 (acceptance)
