    @Test
    public void testIntegrate_SanityCheckFailure() {
        // Arrange
        when(mockEquations.getTime()).thenThrow(new MathIllegalArgumentException("Sanity check failed"));

        // Act & Assert
        assertThrows(MathIllegalArgumentException.class, () -> {
            integrator.integrate(mockEquations, 0.1);
        });
    }

    /**
     * Dummy class to satisfy the compiler for the test
     */
